class TestQLIKE:
    def test_perfect_prediction_is_zero(self):
        y = np.array([-8.0, -9.0, -7.5, -8.5])
        assert qlike(y, y, log_space=True) == pytest.approx(0.0, abs=1e-15)

    def test_positive_for_imperfect(self):
        y = np.array([-8.0, -9.0, -7.5, -8.5])
        h = y + 0.5
        assert qlike(y, h, log_space=True) > 0

